let toastTimer=0;
const tr = (key)=>i18n[lang][key] ?? i18n.en[key] ?? key;
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function translate(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(i18n[lang][key]!=null)el.textContent=tr(key)});$$('[data-i18n-html]').forEach(el=>{el.innerHTML=tr(el.dataset.i18nHtml)});$('language-switch').textContent=lang==='en'?'العربية':'English';$('camera-top-text').textContent=tr(cameraActive?'disableCamera':'enableCamera');$('model-state').textContent=tr(training?'modelTraining':'modelReady');updateTrainButton();updateProblemDescription();renderLessonNav();renderLesson();renderQuiz();updateLivePrediction();updateCoach();}
function markComplete(idx){if(complete[idx])return;complete[idx]=true;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(complete))}catch{}renderLessonNav();renderLesson();toast(tr('readyToTry'));}
function renderLessonNav(){const nav=$('lesson-nav');nav.innerHTML='';lessons[lang].forEach((entry,index)=>{const b=document.createElement('button');b.type='button';b.className=`lesson-item ${index===lesson&&tab==='learn'?'active':''}`;b.innerHTML=`<span class="lesson-index">${String(index+1).padStart(2,'0')}</span><span class="lesson-text"></span>${complete[index]?'<span class="lesson-complete">✓</span>':''}`;b.querySelector('.lesson-text').textContent=entry.nav.split(' · ')[1];b.addEventListener('click',()=>{setTab('learn');setLesson(index)});nav.append(b)})}
function renderLesson(){const entry=lessons[lang][lesson];$('lesson-counter').textContent=`${String(lesson+1).padStart(2,'0')} / 05`;$('learn-progress').style.width=`${(lesson+1)*20}%`;$('lesson-kicker').textContent=entry.kicker;$('lesson-title').textContent=entry.title;$('lesson-body').textContent=entry.body;$('mission-text').textContent=entry.mission;$('mission-state').textContent=complete[lesson]?tr('done'):tr('notYet');$('mission-state').classList.toggle('done',complete[lesson]);$('prev-lesson').disabled=lesson===0;$('next-lesson').querySelector('span').textContent=lesson===4?tr('finish'):tr('nextLesson');$('free-lab-section').hidden=!(tab==='free'||(tab==='learn'&&lesson===3));$('challenge-section').hidden=!(tab==='challenge'||(tab==='learn'&&lesson===4));const learningPanel=$('learning-panel');learningPanel.style.display=tab==='free'?'none':'';$('breadcrumb-current').textContent=tr(tab==='free'?'freeLab':tab==='challenge'?'challenge':'guidedLab');renderInspector();}
function setLesson(index){lesson=Math.max(0,Math.min(4,index));renderLessonNav();renderLesson();if(lesson===3||lesson===4)setTimeout(()=>$(lesson===3?'free-lab-section':'challenge-section').scrollIntoView({behavior:'smooth',block:'nearest'}),100);}
function setTab(next){tab=next;document.querySelector('.workspace-grid').classList.toggle('free-mode',tab==='free');$$('.side-link').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderLessonNav();renderLesson();if(next==='challenge')renderQuiz();if(window.innerWidth<=950)$('sidebar').classList.remove('open');if(next!=='learn')setTimeout(()=>$(next==='free'?'free-lab-section':'challenge-section').scrollIntoView({behavior:'smooth',block:'start'}),100);}
$$('.side-link').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
$('prev-lesson').addEventListener('click',()=>setLesson(lesson-1));
$('next-lesson').addEventListener('click',()=>{if(!complete[lesson]){toast(tr('needMission'));if(lesson===4)$('challenge-section').scrollIntoView({behavior:'smooth'});return;}if(lesson<4)setLesson(lesson+1);else{setTab('challenge');toast(tr('quizFinished'));}});
$('menu-toggle').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
$('language-switch').addEventListener('click',()=>{lang=lang==='en'?'ar':'en';translate()});
$('map-info-btn').addEventListener('click',()=>toast(tr('mapHelp')));

// Real trainable multilayer perceptron: 2 inputs → N tanh hidden units → 1 sigmoid output.
// Full-batch backpropagation + Adam optimizer on actual truth-table examples.
let hiddenCount=4,learningRate=.15,problem='xor',epoch=0,training=false,trainInterval=null,lossHistory=[],net;
let liveInputs=[0,1],mutedHidden=new Set(),inputFlipped=false,hiddenToggled=false,wasTrained=false,hoveredNode=null,handActionCount=0,gestureFeedbackTimer=0;
function trainData(){return [[0,0],[0,1],[1,0],[1,1]].map(([x,y])=>({x:[x,y],y:problem==='xor'?x!==y?1:0:problem==='or'?x||y?1:0:x&&y?1:0}));}
function createNetwork(){const size=4*hiddenCount+1;const params=Array.from({length:size},(_,i)=>{const scale=i<2*hiddenCount?1.25:.75;return(Math.random()*2-1)*scale});return{p:params,m:new Float64Array(size),v:new Float64Array(size)};}
function feedforward(inputs){const n=hiddenCount,w=net.p,hs=new Array(n);for(let j=0;j<n;j++)hs[j]=mutedHidden.has(j)?0:Math.tanh(w[j*2]*inputs[0]+w[j*2+1]*inputs[1]+w[2*n+j]);let z=w[4*n];for(let j=0;j<n;j++)z+=w[3*n+j]*hs[j];const value=1/(1+Math.exp(-Math.max(-30,Math.min(30,z))));return{hidden:hs,out:value};}
function measure(){let loss=0,good=0;for(const sample of trainData()){const pred=feedforward(sample.x).out;loss-=sample.y*Math.log(Math.max(1e-9,pred))+(1-sample.y)*Math.log(Math.max(1e-9,1-pred));if((pred>=.5?1:0)===sample.y)good++;}return{loss:loss/4,accuracy:good/4};}
function trainEpoch(){const n=hiddenCount,w=net.p,grad=new Float64Array(w.length);for(const sample of trainData()){const{hidden:hs,out}=feedforward(sample.x),d=out-sample.y;grad[4*n]+=d;for(let j=0;j<n;j++){grad[3*n+j]+=d*hs[j];const dh=d*w[3*n+j]*(1-hs[j]*hs[j]);grad[j*2]+=dh*sample.x[0];grad[j*2+1]+=dh*sample.x[1];grad[2*n+j]+=dh;}}epoch++;const beta1=.9,beta2=.999;for(let i=0;i<w.length;i++){const g=grad[i]/4;net.m[i]=beta1*net.m[i]+(1-beta1)*g;net.v[i]=beta2*net.v[i]+(1-beta2)*g*g;const mhat=net.m[i]/(1-Math.pow(beta1,epoch));const vhat=net.v[i]/(1-Math.pow(beta2,epoch));w[i]-=learningRate*mhat/(Math.sqrt(vhat)+1e-8);}}
function updateTrainButton(){$('train-btn-text').textContent=tr(training?'pauseTraining':epoch>0?'resumeTraining':'startTraining');$('train-icon').textContent=training?'Ⅱ':'▶';$('model-state').textContent=tr(training?'modelTraining':'modelReady');}
function refreshResults(){const m=measure();$('loss-value').textContent=m.loss.toFixed(3);$('accuracy-value').textContent=Math.round(m.accuracy*100)+'%';$('epochs-value').textContent=epoch.toLocaleString('en-US');if(lesson===2&&!complete[2]&&epoch>=15&&m.accuracy>=.75)markComplete(2);drawLossChart();drawDecisionMap();updateThreeWeights();updateLivePrediction();drawFallbackNetwork();return m;}
function stopTraining(){training=false;if(trainInterval){clearInterval(trainInterval);trainInterval=null;}updateTrainButton();}
function startTraining(){if(training){stopTraining();return;}if(epoch>=1800)resetNetwork();if(mutedHidden.size){mutedHidden.clear();updateNodeVisuals();}wasTrained=true;updateCoach();training=true;updateTrainButton();trainInterval=setInterval(()=>{for(let i=0;i<7;i++)trainEpoch();const m=measure();lossHistory.push({epoch,loss:m.loss});if(lossHistory.length>120)lossHistory.shift();refreshResults();if((epoch>=100&&m.loss<.045&&m.accuracy===1)||epoch>=1800){stopTraining();toast(tr('trainDone'));}},70);}
function resetNetwork(showToast=false){stopTraining();mutedHidden.clear();wasTrained=false;inputFlipped=false;hiddenToggled=false;liveInputs=[0,1];if(selected&&selected.layer==='hidden'&&selected.index>=hiddenCount)selected=null;net=createNetwork();epoch=0;lossHistory=[{epoch:0,loss:measure().loss}];buildNetworkView();refreshResults();updateCoach();if(showToast)toast(tr('modelReset'));}
$('train-btn').addEventListener('click',startTraining);$('reset-model').addEventListener('click',()=>resetNetwork(true));$('randomize-model').addEventListener('click',()=>resetNetwork(true));
$('hidden-slider').addEventListener('input',e=>{const newHidden=Number(e.target.value);if(newHidden===hiddenCount)return;hiddenCount=newHidden;$('hidden-value').textContent=hiddenCount;$('hidden-annotation').textContent=`${hiddenCount} NEURONS`;resetNetwork();if(lesson===3&&!complete[3])markComplete(3);});
$('lr-slider').addEventListener('input',e=>{learningRate=Number(e.target.value);$('lr-value').textContent=learningRate.toFixed(2);resetNetwork();});
$('problem-select').addEventListener('change',e=>{problem=e.target.value;resetNetwork();updateProblemDescription();});
function updateProblemDescription(){$('problem-name').textContent=tr('problem'+problem.charAt(0).toUpperCase()+problem.slice(1));$('problem-description').textContent=tr('problem'+problem.charAt(0).toUpperCase()+problem.slice(1)+'Desc');}

// Every interaction changes the *real* network state, not just a visual effect.
function expectedFor(inputs=liveInputs){const [a,b]=inputs;return problem==='xor'?Number(a!==b):problem==='or'?Number(Boolean(a||b)):Number(Boolean(a&&b));}
function announceAction(message){$('gesture-action-feedback').textContent=message;clearTimeout(gestureFeedbackTimer);$('gesture-action-feedback').classList.add('active');gestureFeedbackTimer=setTimeout(()=>$('gesture-action-feedback').classList.remove('active'),2600);toast(message);}
function flashInteraction(){const el=$('interaction-flash');el.classList.remove('play-flash');void el.offsetWidth;el.classList.add('play-flash');}
function flipInput(index){const prev=feedforward(liveInputs).out;liveInputs[index]=1-liveInputs[index];inputFlipped=true;if(tab==='learn'&&lesson===0&&!complete[0])markComplete(0);selected={layer:'input',index};renderInspector();updateNodeVisuals();refreshResults();drawFallbackNetwork();updateCoach();flashInteraction();const after=feedforward(liveInputs).out;announceAction(lang==='ar'?`تغيّر x${index+1} إلى ${liveInputs[index]} · احتمال الفئة 1: ${Math.round(prev*100)}% ← ${Math.round(after*100)}%`:`x${index+1} switched to ${liveInputs[index]} · P(1): ${Math.round(prev*100)}% → ${Math.round(after*100)}%`);}
function toggleHidden(index){const prev=feedforward(liveInputs).out;if(training)stopTraining();const wasMuted=mutedHidden.has(index);if(wasMuted)mutedHidden.delete(index);else mutedHidden.add(index);hiddenToggled=true;if(tab==='learn'&&lesson===1&&!complete[1])markComplete(1);selected={layer:'hidden',index};renderInspector();updateNodeVisuals();refreshResults();drawFallbackNetwork();updateCoach();flashInteraction();const after=feedforward(liveInputs).out;announceAction(lang==='ar'?`الخلية المخفية ${index+1}: ${wasMuted?'اشتغلت مجددًا':'معطّلة مؤقتًا'} · P(1): ${Math.round(prev*100)}% ← ${Math.round(after*100)}%`:`Hidden ${index+1} ${wasMuted?'restored':'muted'} · P(1): ${Math.round(prev*100)}% → ${Math.round(after*100)}%`);}
function updateLivePrediction(){if(!net)return;const p=feedforward(liveInputs).out;const pred=Number(p>=.5),correct=expectedFor();for(let i=0;i<2;i++){$('live-input-'+i).textContent=liveInputs[i];$('flip-input-'+i).classList.toggle('bit-on',Boolean(liveInputs[i]));}$('live-prediction').textContent=pred;$('live-expected').textContent=correct;$('live-confidence').textContent=`P(1) = ${(p*100).toFixed(1)}%`;$('live-result-feedback').textContent=pred===correct?(lang==='ar'?'✓ توقع صحيح':'✓ Correct'):(lang==='ar'?'× توقع خاطئ':'× Incorrect');$('live-result-feedback').classList.toggle('wrong',pred!==correct);const explanation=lang==='ar'?`XOR: عندما يختلف المدخلان تكون الإجابة 1. التوقع الحالي ${pred===correct?'صحيح':'غير صحيح'}. الدقة بالأعلى تحسب 4 حالات، لذلك قد تبقى 100% عند تغيير المثال فقط.`:`XOR: different inputs mean 1. This prediction is ${pred===correct?'correct':'incorrect'}. The accuracy above evaluates all 4 cases, so switching inputs alone will not change it.`;const logic=lang==='ar'?`المسألة ${problem.toUpperCase()} · القيمة الصحيحة لهذا الإدخال ${correct}. ${mutedHidden.size?'هناك خلايا مخفية معطّلة مؤقتًا.':'غيّري المدخلات لتشاهدي توقعًا مختلفًا.'}`:`${problem.toUpperCase()} · Correct answer for this pair: ${correct}. ${mutedHidden.size?'Some hidden neurons are muted.':'Flip inputs to explore different predictions.'}`;$('play-explanation').textContent=problem==='xor'?explanation:logic;}
function updateCoach(){const m=net?measure():null;let title,hint,step;if(!inputFlipped){title=lang==='ar'?'المهمة 1: غيّري الرقم!':'Mission 1: Flip the number!';hint=lang==='ar'?'وجّهي السبابة إلى دائرة زرقاء وضمي الإصبعين عندها. المفروض تتغير قيمة 0 أو 1.' :'Aim at a BLUE neuron. Pinch your thumb and index finger to change its input 0 ↔ 1.';step='01 / 03';}
else if(!wasTrained||!epoch){title=lang==='ar'?'المهمة 2: علّمي الشبكة!':'Mission 2: Train the network!';hint=lang==='ar'?'افتحي كفك وثبّتيه ثانية لبدء التدريب. راقبي تغير Loss وAccuracy.' :'Hold an OPEN PALM for 1 second to train. Watch Loss and Accuracy change.';step='02 / 03';}
else if(!hiddenToggled){title=lang==='ar'?'المهمة 3: عطّلي خلية!':'Mission 3: Break a neuron!';hint=lang==='ar'?'وجّهي السبابة إلى دائرة بنفسجية واعملي Pinch لتعطيلها. قارني التوقع والخطأ.' :'Aim at a PURPLE neuron and pinch to mute it. Compare the prediction and loss.';step='03 / 03';}
else{title=lang==='ar'?'رائع! كمّلي التجربة.':'Amazing. Keep experimenting!';hint=lang==='ar'?'جرّبي تبديل المدخلات وتعطيل خلايا أخرى، أو اقبضي يدك 1.5 ثانية لإعادة النموذج.' :'Try other input pairs, mute more nodes, or hold a FIST for 1.5 seconds to reset.';step='✓ 03 / 03';}
$('coach-title').textContent=title;$('coach-hint').textContent=hint;$('coach-step').textContent=step;$('coach-move-status').textContent=lang==='ar'?(m&&m.accuracy===1?'✓ الدقة 100% — اختبري خلايا أخرى':'✦ جرّبي بنفسك'):(m&&m.accuracy===1?'✓ 100% training accuracy — experiment!':'✦ Your turn to experiment');}
$('flip-input-0').addEventListener('click',()=>flipInput(0));$('flip-input-1').addEventListener('click',()=>flipInput(1));

// Data visualization is drawn directly from the mathematical model's actual predictions.
function setupCanvas(canvas){const r=canvas.getBoundingClientRect();const w=Math.max(1,r.width),h=Math.max(1,r.height),dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{ctx,w,h};}
function drawLossChart(){const{ctx,w,h}=setupCanvas($('loss-chart'));ctx.clearRect(0,0,w,h);const pad={left:6,right:6,top:8,bottom:12};for(let k=0;k<3;k++){const y=pad.top+(h-pad.top-pad.bottom)*k/2;ctx.strokeStyle='#313c55';ctx.lineWidth=1;ctx.setLineDash([3,5]);ctx.beginPath();ctx.moveTo(pad.left,y);ctx.lineTo(w-pad.right,y);ctx.stroke();}ctx.setLineDash([]);if(!lossHistory.length)return;const maxY=Math.max(.75,...lossHistory.map(d=>d.loss))*1.08;const minEpoch=lossHistory[0].epoch,maxEpoch=Math.max(minEpoch+1,lossHistory[lossHistory.length-1].epoch);const points=lossHistory.map(p=>({x:pad.left+(w-pad.left-pad.right)*(p.epoch-minEpoch)/(maxEpoch-minEpoch),y:pad.top+(h-pad.top-pad.bottom)*(1-p.loss/maxY)}));if(points.length===1)points.push({...points[0],x:w-pad.right});const area=ctx.createLinearGradient(0,0,0,h);area.addColorStop(0,'#a694f84a');area.addColorStop(1,'#a694f800');ctx.beginPath();ctx.moveTo(points[0].x,h-pad.bottom);for(const p of points)ctx.lineTo(p.x,p.y);ctx.lineTo(points[points.length-1].x,h-pad.bottom);ctx.closePath();ctx.fillStyle=area;ctx.fill();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#b9adff';ctx.lineWidth=2.6;ctx.lineJoin='round';ctx.stroke();const last=points[points.length-1];ctx.beginPath();ctx.arc(last.x,last.y,3.5,0,Math.PI*2);ctx.fillStyle='#dfd5ff';ctx.fill();}
function drawDecisionMap(){const canvas=$('decision-map'),ctx=canvas.getContext('2d');const W=canvas.width,H=canvas.height,grid=46,cell=W/grid;for(let gy=0;gy<grid;gy++)for(let gx=0;gx<grid;gx++){const p=feedforward([gx/(grid-1),1-gy/(grid-1)]).out;const r=Math.round(107*(1-p)+238*p),g=Math.round(108*(1-p)+145*p),b=Math.round(197*(1-p)+159*p);ctx.fillStyle=`rgb(${r},${g},${b})`;ctx.fillRect(gx*cell,gy*cell,cell+1,cell+1);}ctx.strokeStyle='#ffffff24';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(W/2,0);ctx.lineTo(W/2,H);ctx.moveTo(0,H/2);ctx.lineTo(W,H/2);ctx.stroke();for(const s of trainData()){const x=18+(W-36)*s.x[0],y=H-18-(H-36)*s.x[1];ctx.beginPath();ctx.arc(x,y,8,0,Math.PI*2);ctx.fillStyle=s.y?'#ffb4b7':'#c1c4ff';ctx.fill();ctx.lineWidth=2;ctx.strokeStyle='#1d243c';ctx.stroke();ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fillStyle='#101624';ctx.fill();}}

// Checkpoint quiz: not fake AI, the questions validate the actual content of the lab.
function renderQuiz(){const qs=questions[lang];if(quizIndex>=qs.length){$('quiz-progress').textContent=lang==='ar'?'انتهى الاختبار':'CHALLENGE COMPLETE';$('quiz-question').textContent=quizScore>=2?tr('quizFinished'):tr('quizTryAgain');$('quiz-options').innerHTML='';$('quiz-score').textContent=`${quizScore} / 3`;$('quiz-feedback').textContent=quizScore>=2?(lang==='ar'?'أكملتِ الدروس بنجاح. رائع!':'Nice work! You finished the learning path.'):(lang==='ar'?'حاولي مراجعة الدروس.':'Review the lesson explanations and try again.');$('quiz-next').disabled=false;$('quiz-next').querySelector('span').textContent=tr('restartQuiz');if(quizScore>=2&&!complete[4])markComplete(4);return;}
const q=qs[quizIndex];$('quiz-progress').textContent=lang==='ar'?`السؤال ${quizIndex+1} من 3`:`QUESTION ${quizIndex+1} OF 3`;$('quiz-score').textContent=`${quizScore} / 3`;$('quiz-question').textContent=q.q;$('quiz-options').innerHTML='';q.opts.forEach((option,idx)=>{const b=document.createElement('button');b.className='quiz-option';b.type='button';b.textContent=String.fromCharCode(65+idx)+'.  '+option;if(quizAnswered){b.disabled=true;if(idx===q.answer)b.classList.add('correct');}b.addEventListener('click',()=>answerQuiz(idx));$('quiz-options').append(b);});$('quiz-feedback').textContent='';$('quiz-next').disabled=!quizAnswered;$('quiz-next').querySelector('span').textContent=tr('nextQuestion');}
function answerQuiz(choice){if(quizAnswered)return;const q=questions[lang][quizIndex];quizAnswered=true;const right=choice===q.answer;if(right)quizScore++;const buttons=$$('.quiz-option');buttons.forEach((b,i)=>{b.disabled=true;if(i===q.answer)b.classList.add('correct');else if(i===choice)b.classList.add('incorrect')});$('quiz-feedback').textContent=tr(right?'checkCorrect':'checkIncorrect')+q.explain;$('quiz-next').disabled=false;$('quiz-score').textContent=`${quizScore} / 3`;}
$('quiz-next').addEventListener('click',()=>{if(quizIndex>=questions[lang].length){quizIndex=0;quizScore=0;quizAnswered=false;}else{quizIndex++;quizAnswered=false;}renderQuiz();});

// 3D rendering: Three.js is optional at runtime. If the public CDN is unreachable,
// the educational simulation still works and a 2D neural canvas is shown.
let THREE=null,renderer=null,scene=null,camera=null,networkRoot=null,visualNodes=[],visualEdges=[];
let pointerStart=null,dragging=false,dragMoved=false,visualMotion=true,lastFrame=0,handX=null;
const stage=$('network-stage');
function nodePositions(){const entries=[];for(let i=0;i<2;i++)entries.push({layer:'input',index:i,x:-3.65,y:(.5-i)*2.25,z:0});for(let j=0;j<hiddenCount;j++)entries.push({layer:'hidden',index:j,x:0,y:((hiddenCount-1)/2-j)*Math.min(.99,5.3/Math.max(1,hiddenCount-1)),z:0});entries.push({layer:'output',index:0,x:3.65,y:0,z:0});return entries;}
function selectNode(layer,index){selected={layer,index};if(layer==='input')return flipInput(index);if(layer==='hidden')return toggleHidden(index);renderInspector();updateNodeVisuals();flashInteraction();const p=feedforward(liveInputs).out;announceAction(lang==='ar'?`المخرج: النموذج يتوقع ${Number(p>=.5)} (احتمال 1 = ${Math.round(p*100)}%)`:`Output: model predicts ${Number(p>=.5)} (P(1) = ${Math.round(p*100)}%)`);}
function renderInspector(){if(!selected){$('inspector-name').textContent=tr('nothingSelected');$('inspector-description').textContent=tr('selectHint');return;}const{layer,index}=selected;const id=`${layer==='input'?'x':layer==='hidden'?'h':'ŷ'}${index+1}`;$('inspector-name').textContent=`${tr('select'+layer.charAt(0).toUpperCase()+layer.slice(1))} · ${id}`;let description=tr('selected'+layer.charAt(0).toUpperCase()+layer.slice(1)+'Desc');if(layer==='input')description+=` · x${index+1} = ${liveInputs[index]}`;if(layer==='hidden')description+=` · ${mutedHidden.has(index)?(lang==='ar'?'معطّلة':'MUTED'):(lang==='ar'?'نشطة':'ACTIVE')} · w=[${net.p[index*2].toFixed(2)}, ${net.p[index*2+1].toFixed(2)}]`;if(layer==='output')description+=` · P(1)=${feedforward(liveInputs).out.toFixed(3)}`;$('inspector-description').textContent=description;}
function updateNodeVisuals(){if(!THREE||!visualNodes.length){drawFallbackNetwork();return;}for(const entry of visualNodes){const{layer,index}=entry.meta,muted=layer==='hidden'&&mutedHidden.has(index),chosen=selected&&layer===selected.layer&&index===selected.index,hover=hoveredNode&&layer===hoveredNode.layer&&index===hoveredNode.index;if(layer==='output'){const c=feedforward(liveInputs).out>=.5?0x82efd5:0xf2a3b5;entry.mesh.material.emissive.setHex(c);entry.mesh.material.color.setHex(c);}entry.mesh.material.emissiveIntensity=muted?.03:hover?3.3:chosen?2.9:layer==='input'&&liveInputs[index]===1?2.0:layer==='input'?.55:1.2;entry.mesh.material.opacity=muted?.17:.98;entry.mesh.scale.setScalar(hover?1.43:chosen?1.3:1);entry.ring.material.opacity=muted?.1:hover?.98:chosen?.9:.27;entry.ring.scale.setScalar(hover?1.17:1);}for(const edge of visualEdges){const blocked=edge.metaLayer==='hidden'&&mutedHidden.has(edge.metaIndex);edge.line.visible=!blocked;edge.pulse.visible=!blocked;}}
function highlightSelected(){updateNodeVisuals();}
function buildNetworkView(){if(!THREE||!scene||!networkRoot){drawFallbackNetwork();return;}while(networkRoot.children.length){const child=networkRoot.children[0];networkRoot.remove(child);child.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose()}})}visualNodes=[];visualEdges=[];const positions=nodePositions();const colors={input:0x89baff,hidden:0xb49bff,output:0x8de9cc};for(const pos of positions){const c=colors[pos.layer],group=new THREE.Group();group.position.set(pos.x,pos.y,pos.z);const glow=new THREE.Mesh(new THREE.SphereGeometry(.45,20,20),new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:.09,depthWrite:false}));group.add(glow);const mesh=new THREE.Mesh(new THREE.SphereGeometry(.29,28,22),new THREE.MeshPhysicalMaterial({color:c,metalness:.18,roughness:.18,emissive:c,emissiveIntensity:1.2,transparent:true,opacity:.98}));mesh.userData={layer:pos.layer,index:pos.index};group.add(mesh);const ring=new THREE.Mesh(new THREE.TorusGeometry(.39,.012,8,50),new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:.26}));ring.rotation.x=Math.PI/2.5;group.add(ring);networkRoot.add(group);visualNodes.push({meta:pos,mesh,ring,group});}
const addEdge=(src,dst,paramIndex)=>{const start=new THREE.Vector3(src.x,src.y,src.z),end=new THREE.Vector3(dst.x,dst.y,dst.z);const geo=new THREE.BufferGeometry().setFromPoints([start,end]);const mat=new THREE.LineBasicMaterial({color:0x786fba,transparent:true,opacity:.25});const line=new THREE.Line(geo,mat);networkRoot.add(line);const pulse=new THREE.Mesh(new THREE.SphereGeometry(.055,9,9),new THREE.MeshBasicMaterial({color:0xb9b2ff,transparent:true,opacity:.9,depthWrite:false}));pulse.position.copy(start);networkRoot.add(pulse);visualEdges.push({start,end,line,mat,pulse,paramIndex,phase:Math.random(),metaLayer:'hidden',metaIndex:dst.layer==='hidden'?dst.index:src.index});};
const ins=positions.filter(p=>p.layer==='input'),hs=positions.filter(p=>p.layer==='hidden'),out=positions.find(p=>p.layer==='output');hs.forEach((h,j)=>ins.forEach((input,i)=>addEdge(input,h,2*j+i)));hs.forEach((h,j)=>addEdge(h,out,3*hiddenCount+j));highlightSelected();updateThreeWeights();updateNodeVisuals();}
function updateThreeWeights(){if(!THREE||!net)return;for(const edge of visualEdges){const weight=net.p[edge.paramIndex],mag=Math.min(1,Math.abs(weight)/3);edge.mat.color.setHex(weight>=0?0x8eced1:0xb29bf5);edge.mat.opacity=.14+mag*.57;edge.pulse.material.color.setHex(weight>=0?0x8de5d1:0xc5afff);}updateNodeVisuals();}
async function initThree(){try{THREE=await import('three');scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(41,1,.1,100);camera.position.set(0,.25,13.65);networkRoot=new THREE.Group();networkRoot.rotation.y=-.10;scene.add(networkRoot);const ambient=new THREE.AmbientLight(0xd9e6ff,1.7);scene.add(ambient);const key=new THREE.PointLight(0xa696ff,22);key.position.set(-2,4,6);scene.add(key);const fill=new THREE.PointLight(0x8ddfee,12);fill.position.set(3,-2,5);scene.add(fill);renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.domElement.setAttribute('aria-label','3D interactive neural network. Click a node to learn more.');$('three-host').append(renderer.domElement);$('fallback-canvas').style.display='none';resizeNetwork();buildNetworkView();requestAnimationFrame(animateThree);}catch(err){console.warn('NeuroHands: Three.js unavailable; 2D fallback active',err);THREE=null;renderer=null;scene=null;networkRoot=null;$('three-host').innerHTML='';$('fallback-canvas').style.display='block';drawFallbackNetwork();}}
function resizeNetwork(){const width=stage.clientWidth,height=stage.clientHeight;if(camera&&renderer){camera.aspect=width/Math.max(1,height);camera.updateProjectionMatrix();renderer.setSize(width,height,false)}drawFallbackNetwork();}
function animateThree(t){if(!renderer||!scene||!camera)return;requestAnimationFrame(animateThree);if(document.hidden)return;const dt=Math.min(.055,(t-lastFrame)/1000||.016);lastFrame=t;if(visualMotion){visualNodes.forEach((entry,i)=>{entry.ring.rotation.y+=dt*(.3+i*.025);entry.group.position.z=Math.sin(t*.0007+i*.7)*.045;});for(const edge of visualEdges){edge.phase=(edge.phase+dt*(training?.55:.15))%1;edge.pulse.position.lerpVectors(edge.start,edge.end,edge.phase);edge.pulse.material.opacity=training?.9:.4;}}if(handX!==null&&!dragging)networkRoot.rotation.y+=(.25*(handX-.5)-networkRoot.rotation.y)*.045;renderer.render(scene,camera);}
function drawFallbackNetwork(){if(THREE&&renderer)return;const el=$('fallback-canvas'),{ctx,w,h}=setupCanvas(el);ctx.clearRect(0,0,w,h);const pts=nodePositions().map(p=>({...p,px:w/2+p.x*w/9.5,py:h/2-p.y*h/7.2}));const ins=pts.filter(p=>p.layer==='input'),hs=pts.filter(p=>p.layer==='hidden'),out=pts.find(p=>p.layer==='output');for(const hidden of hs)for(const input of ins){ctx.beginPath();ctx.moveTo(input.px,input.py);ctx.lineTo(hidden.px,hidden.py);ctx.strokeStyle='#9886dd60';ctx.lineWidth=1.7;ctx.stroke();}for(const hidden of hs){ctx.beginPath();ctx.moveTo(hidden.px,hidden.py);ctx.lineTo(out.px,out.py);ctx.strokeStyle='#8bd7d569';ctx.lineWidth=1.7;ctx.stroke();}for(const p of pts){const color=p.layer==='input'?'#8bbaff':p.layer==='hidden'?'#b5a3ff':'#8ee3c8';const selectedNow=selected&&selected.layer===p.layer&&selected.index===p.index,hover=hoveredNode&&hoveredNode.layer===p.layer&&hoveredNode.index===p.index,muted=p.layer==='hidden'&&mutedHidden.has(p.index);ctx.shadowBlur=hover?45:selectedNow?34:24;ctx.shadowColor=color;ctx.beginPath();ctx.arc(p.px,p.py,hover?16:selectedNow?13:10,0,Math.PI*2);ctx.fillStyle=muted?'#39415b':color;ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.arc(p.px,p.py,hover?24:selectedNow?21:17,0,Math.PI*2);ctx.strokeStyle=muted?'#6b648988':color+'88';ctx.lineWidth=1.5;ctx.stroke();if(p.layer==='input'||muted||p.layer==='output'){ctx.fillStyle='#eaf4ff';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';const v=p.layer==='input'?liveInputs[p.index]:p.layer==='output'?Number(feedforward(liveInputs).out>=.5):'×';ctx.fillText(String(v),p.px,p.py);}}}
function nearestNode(normX,normY){const w=stage.clientWidth,h=stage.clientHeight;let best=null,bestDistance=Infinity;if(THREE&&renderer&&camera&&visualNodes.length){networkRoot.updateMatrixWorld(true);for(const entry of visualNodes){const p=entry.mesh.getWorldPosition(new THREE.Vector3()).project(camera);const x=(p.x+1)*.5*w,y=(1-p.y)*.5*h;const d=Math.hypot(normX*w-x,normY*h-y);if(d<bestDistance){bestDistance=d;best={layer:entry.meta.layer,index:entry.meta.index};}}}else{for(const node of nodePositions()){const x=w/2+node.x*w/9.5,y=h/2-node.y*h/7.2;const d=Math.hypot(normX*w-x,normY*h-y);if(d<bestDistance){bestDistance=d;best={layer:node.layer,index:node.index};}}}return bestDistance<Math.min(160,Math.max(94,w*.24))?best:null;}
function setHovered(node){const same=(hoveredNode?.layer===node?.layer)&&(hoveredNode?.index===node?.index);hoveredNode=node;if(!same)updateNodeVisuals();const label=$('hand-target');if(!node){label.textContent=lang==='ar'?'وجّهي يدك للدائرة':'AIM AT A NEURON';return;}label.textContent=node.layer==='input'?`x${node.index+1} = ${liveInputs[node.index]} · ${lang==='ar'?'ضمّي الإصبعين لتغيير':'PINCH TO FLIP'}`:node.layer==='hidden'?`H${node.index+1} · ${lang==='ar'?'ضمّي الإصبعين للتعطيل':'PINCH TO MUTE'}`:`OUTPUT · ${lang==='ar'?'ضمّي الإصبعين للفحص':'PINCH TO INSPECT'}`;}
function pickNode(normX,normY){const hit=nearestNode(normX,normY);if(hit){selectNode(hit.layer,hit.index);return true;}return false;}
let dragOrigin=null;
stage.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;dragOrigin={x:e.clientX,y:e.clientY,rotation:networkRoot?.rotation.y??0};dragMoved=false;stage.setPointerCapture(e.pointerId);});
stage.addEventListener('pointermove',e=>{const rect=stage.getBoundingClientRect();if(!cameraActive)setHovered(nearestNode((e.clientX-rect.left)/rect.width,(e.clientY-rect.top)/rect.height));if(!dragOrigin)return;const d=e.clientX-dragOrigin.x;if(Math.abs(d)>5||Math.abs(e.clientY-dragOrigin.y)>5)dragMoved=true;if(THREE&&networkRoot)networkRoot.rotation.y=dragOrigin.rotation+d*.006;});
stage.addEventListener('pointerup',e=>{if(!dragOrigin)return;dragOrigin=null;if(!dragMoved){const rect=stage.getBoundingClientRect();pickNode((e.clientX-rect.left)/rect.width,(e.clientY-rect.top)/rect.height);}});
stage.addEventListener('pointercancel',()=>dragOrigin=null);stage.addEventListener('pointerleave',()=>{if(!cameraActive)setHovered(null);});
$('reset-view').addEventListener('click',()=>{if(networkRoot)networkRoot.rotation.y=-.1;else drawFallbackNetwork();});
$('toggle-motion').addEventListener('click',()=>{visualMotion=!visualMotion;$('toggle-motion').textContent=visualMotion?'Ⅱ':'▶';});

// MediaPipe Hand Landmarker: processed entirely inside the user's browser.
// No frames, landmarks, or recordings are uploaded to an app backend.
let cameraActive=false,mediaStream=null,handLandmarker=null,cameraFrame=0,lastVideoTime=-1,lastDetect=0;
let wasPinching=false,openPalmSince=0,lastPalmTrigger=0,fistSince=0,fistLatched=false,openLatched=false;
const handEdges=[[0,1],[1,2],[2,3],[3,4],[0,5],[5,6],[6,7],[7,8],[5,9],[9,10],[10,11],[11,12],[9,13],[13,14],[14,15],[15,16],[13,17],[0,17],[17,18],[18,19],[19,20]];
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
async function cameraToggle(){if(cameraActive){stopCamera();return;}if(!navigator.mediaDevices?.getUserMedia){toast(tr('cameraSecure'));return;}
$('camera-top-btn').disabled=true;toast(tr('cameraLoading'));try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:'user',width:{ideal:640},height:{ideal:480}}});const video=$('camera-video');video.srcObject=mediaStream;await video.play();$('camera-float').hidden=false;const mp=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.22-rc.20250304/vision_bundle.mjs');const vision=await mp.FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.22-rc.20250304/wasm');const modelUrl='https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task';try{handLandmarker=await mp.HandLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:modelUrl,delegate:'GPU'},runningMode:'VIDEO',numHands:1});}catch{handLandmarker=await mp.HandLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:modelUrl,delegate:'CPU'},runningMode:'VIDEO',numHands:1});}cameraActive=true;$('camera-top-btn').classList.add('connected');$('camera-top-text').textContent=tr('disableCamera');wasPinching=false;openPalmSince=0;fistSince=0;fistLatched=false;openLatched=false;lastVideoTime=-1;lastDetect=0;cameraFrame=requestAnimationFrame(processCameraFrame);toast(tr('cameraActive'));}
catch(err){console.warn('Camera initialization failed',err);stopCamera(false);toast(err?.name==='NotAllowedError'||err?.name==='NotFoundError'?tr('cameraFailed'):tr('cameraTrackerFailed'));}finally{$('camera-top-btn').disabled=false;}}
function stopCamera(showToast=true){cameraActive=false;if(cameraFrame)cancelAnimationFrame(cameraFrame);cameraFrame=0;if(handLandmarker){try{handLandmarker.close()}catch{}}handLandmarker=null;if(mediaStream)for(const track of mediaStream.getTracks())track.stop();mediaStream=null;$('camera-video').srcObject=null;$('camera-float').hidden=true;$('camera-top-btn').classList.remove('connected');$('camera-top-text').textContent=tr('enableCamera');$('hand-cursor').style.display='none';handX=null;wasPinching=false;openPalmSince=0;fistSince=0;fistLatched=false;openLatched=false;setHovered(null);lastVideoTime=-1;if(showToast)toast(tr('cameraStopped'));}
function processCameraFrame(now){if(!cameraActive||!handLandmarker)return;cameraFrame=requestAnimationFrame(processCameraFrame);const video=$('camera-video');if(video.readyState<2||now-lastDetect<55||lastVideoTime===video.currentTime)return;lastDetect=now;lastVideoTime=video.currentTime;let result;try{result=handLandmarker.detectForVideo(video,now);}catch(err){console.warn('Hand landmark detection error',err);return;}const landmarks=result?.landmarks?.[0];paintHand(landmarks);if(!landmarks){$('gesture-label').textContent=tr('gestureLooking');$('hand-cursor').style.display='none';openPalmSince=0;fistSince=0;wasPinching=false;handX=null;setHovered(null);return;}
const point=landmarks[8];handX=Math.min(1,Math.max(0,1-point.x));const pointerY=Math.min(1,Math.max(0,point.y));const handCursor=$('hand-cursor');handCursor.style.display='block';handCursor.style.left=(handX*100)+'%';handCursor.style.top=(pointerY*100)+'%';const target=nearestNode(handX,pointerY);setHovered(target);
const palmSize=Math.max(.035,dist(landmarks[0],landmarks[9]));const pinchDistance=dist(landmarks[4],landmarks[8])/palmSize;const pinch=wasPinching?pinchDistance<.88:pinchDistance<.60;handCursor.classList.toggle('pinching',pinch);
const isExtended=(tip)=>dist(landmarks[tip],landmarks[0])>dist(landmarks[tip-2],landmarks[0])*1.12;
const openCount=[8,12,16,20].filter(isExtended).length;
const isOpen=openCount>=4&&!pinch;
const isFist=openCount<=1&&!pinch&&dist(landmarks[4],landmarks[9])<palmSize*2.3;
if(pinch&&!wasPinching){if(target){selectNode(target.layer,target.index);$('gesture-label').textContent=tr('gesturePinch');}else{announceAction(lang==='ar'?'وجّهي المؤشر فوق إحدى الدوائر المضيئة ثم ضمي إصبعيك.':'Aim at a glowing neuron first, then pinch.');}}
if(isOpen){fistSince=0;fistLatched=false;$('gesture-label').textContent=tr('gestureOpen');if(!openPalmSince)openPalmSince=now;if(now-openPalmSince>950&&!openLatched){openLatched=true;openPalmSince=0;if(!training){if(epoch>0&&measure().accuracy===1&&measure().loss<.06){announceAction(lang==='ar'?'الشبكة مدرّبة بالفعل! جرّبي تغيير المدخلات أو تعطيل خلية، أو اقبضي يدك لإعادة التدريب.':'Already trained! Flip inputs, mute a neuron, or hold a fist to reset.');}else{startTraining();lastPalmTrigger=now;$('gesture-label').textContent=tr('gestureTrain');announceAction(lang==='ar'?'بدأ التدريب! لاحظي كيف تتغير الدقة والخطأ.':'Training started! Watch the accuracy and loss.');}}}}else{openPalmSince=0;openLatched=false;}
if(isFist){if(!fistSince)fistSince=now;if(!fistLatched&&now-fistSince>1450){fistLatched=true;resetNetwork(true);updateCoach();announceAction(lang==='ar'?'✊ بدأنا من جديد! الآن افتحي كفك للتدريب.':'✊ Model reset! Open your palm to retrain.');}$('gesture-label').textContent=lang==='ar'?'✊ اثبتي للعودة للبداية':'✊ HOLD TO RESET';}
else{fistSince=0;fistLatched=false;if(!isOpen&&!pinch)$('gesture-label').textContent=target?(lang==='ar'?'✓ موجّهة إلى خلية · ضمي الإصبعين':'✓ TARGET LOCKED · PINCH'):tr('gesturePoint');}
wasPinching=pinch;
}
function paintHand(points){const canvas=$('hand-overlay'),video=$('camera-video');const w=video.videoWidth||640,h=video.videoHeight||480;if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}const ctx=canvas.getContext('2d');ctx.clearRect(0,0,w,h);if(!points)return;ctx.lineCap='round';for(const[a,b]of handEdges){ctx.beginPath();ctx.moveTo(points[a].x*w,points[a].y*h);ctx.lineTo(points[b].x*w,points[b].y*h);ctx.strokeStyle='#b4a4ffbd';ctx.lineWidth=3;ctx.stroke();}for(const point of points){ctx.beginPath();ctx.arc(point.x*w,point.y*h,4,0,Math.PI*2);ctx.fillStyle='#c4ffff';ctx.fill();}}
$('camera-top-btn').addEventListener('click',cameraToggle);$('close-camera').addEventListener('click',()=>stopCamera());
window.addEventListener('pagehide',()=>{if(cameraActive)stopCamera(false);});
window.addEventListener('resize',()=>{resizeNetwork();drawLossChart();drawDecisionMap();});

// Boot. All core lessons, quizzes, training and charts work before external 3D loads.
net=createNetwork();lossHistory=[{epoch:0,loss:measure().loss}];translate();refreshResults();updateCoach();drawFallbackNetwork();initThree();
